  signal: controller.signal
})
  .then(response => response.json())
  .then(data => console.log(data))
  .catch(error => {
    if (error.name === "AbortError") {
      console.log("Request was cancelled");
    } else {
      console.error(error);
    }
  });

// Cancel the request
controller.abort();

